//function for vibrating the mobile
function vibrate() 
{
  if (!window) 
  {
    return;
  }    
  if (!window.navigator) 
  {
    return;
  }
  if (!window.navigator.vibrate) 
  {
    return;
  }
  window.navigator.vibrate(100);
}


export default Main;