import React from 'react'
import { SideBarData } from './SideBarData';
import { thisDay } from '../Pages/Main';
import { format } from 'date-fns';
import DateRangeIcon from '@mui/icons-material/DateRange';

function SideBar() {

  function Logout(val){
    localStorage.removeItem('user');
    window.location = val.link
  }

  return (
    <div className='sidebar'>
      <span>
      <br></br>
      <span style={{display: 'flex', flexDirection: 'row'}}>
          <DateRangeIcon style={{marginLeft: 20, color: 'white', marginTop: 5}}/>
          <h3 className='normal-label' style={{color: 'white', fontSize: 14, textTransform: 'uppercase', letterSpacing: 0, marginLeft: 5 }}>
            {format(new Date(thisDay), "dd-MMM-yy")} 
          <br></br>V: 3.2.1</h3>
        </span>
        </span>
        <ul className='sidebarlist'>
            {SideBarData.map((val, key) => {
                return<li key={key} className='row' onClick={()=>{val.title !== 'Logout' ? window.location = val.link : Logout(val)}}>
                        {""}
                        <div id='icon'>{val.icon}</div>
                        <div id='title'>{val.title}</div>
                      </li>
            })}
        </ul>
    </div>
  )
}

export default SideBar