// Statistics.js
import React, { useEffect, useState } from 'react';
import { fetchWeightBasedOnDate } from '../API/FetchAllDetailsAPI';
import HomeIcon from '@mui/icons-material/Home';
import '../css/Report.css'; 
import { useNavigate } from 'react-router-dom';


let membersCount = localStorage.getItem('members') === null ? 1 : localStorage.getItem('members');
let count = membersCount !== 1 ? membersCount.length : 1
function Report() {
  const [state, setState] = useState([]);
  const [sortConfig, setSortConfig] = useState({ key: null, direction: 'asc' });
  const navigate = useNavigate();

  useEffect(() => {
    // Call fetchTeamMembers to initialize teamMembers
    
    fetchUserWeightData();
}, []); // No need to include userName as a dependency

const fetchUserWeightData = async () => {
    try {
        // Call the API function for each member
        const MembersList = await fetchWeightBasedOnDate(localStorage.getItem('user'))
        setState(MembersList);
    } catch (error) {
        console.error('Error fetching weight data:', error);
    } finally {
        // Always close the modal, whether the request was successful or not
    }
};

  const sortData = (key) => {
    let direction = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
  
    const sorted = [...state].sort((a, b) => {
      const aValue = Number(a[key]);
      const bValue = Number(b[key]);
  
      if (isNaN(aValue) || isNaN(bValue)) {
        // If the values are not numbers, perform string comparison
        if (a[key] < b[key]) {
            return direction === 'asc' ? -1 : 1;
          }
          if (a[key] > b[key]) {
            return direction === 'asc' ? 1 : -1;
          }
      }
  
      // Numeric comparison
      return (direction === 'asc') ? aValue - bValue : bValue - aValue;
    });
  
    setSortConfig({ key, direction });
    setState(sorted);
  };

    return (
      
        <div className="table-container">
            <span style={{display: 'flex', flexDirection: 'row', alignItems: 'center'}}>
              <button onClick={() => {navigate('/')}} style={{width: 'fit-content', alignItems: 'center', justifyContent:'center', border: 0, backgroundColor: 'black', color: 'white',  padding:10, cursor: 'pointer'}}>
              <HomeIcon /></button>
              <p style={{marginLeft: 10, textTransform: 'capitalize', fontWeight: 400, fontSize: 14}}>Home</p>
            </span>
            {/* Your modal code here */}
            {count > 1 && state !== null ? (
              <>
            <h2>Team Members</h2>
            <table className="styled-table">
        <thead>
          <tr>
          <th onClick={() => sortData('SNo')}>SNo</th>
            <th onClick={() => sortData('EntryUser')}>User Name</th>
            <th onClick={() => sortData('InitialDate')}>Initial Weight</th>
            <th onClick={() => sortData('TargetWeight')}>Target Weight</th>
            <th onClick={() => sortData('TodayWeight')}>Today's Weight</th>
            <th onClick={() => sortData('yesterdayWeight')}>Last Available Weight</th>
            <th onClick={() => sortData('Need to Achieve')}>Deviation from Target Weight</th>
            {/* Add more headers as needed */}
          </tr>
        </thead>
        <tbody>
          {state !== null ? state.map((item, index) => (
            <tr key={index}>
              <td>{index +1}</td>
              <td style={{textTransform: 'capitalize'}}>{item.EntryUser}</td>
              <td>{item.InitialDate}</td>
              <td>{item.TargetWeight}</td>
              <td>{item.TodayWeight === null ? 0 : item.TodayWeight}</td>
              <td>{item.lastAvailableWeight === null ? 0 : item.lastAvailableWeight}</td>
              <td>{item['Need to Achieve']}</td>
              {/* Add more cells as needed */}
            </tr>
          )) : <></>}
        </tbody>
      </table>
        </>
     ) : (
        <p>No Team Members Available</p>
     )}
     </div>
    );
}

export default Report;