import React, { useEffect, useState } from 'react';
import logo from '../Images/BNutritions Logo.png';
import '../App.css';
import { message, Spin } from 'antd';
import { api } from '../API/FetchAllDetailsAPI';
import { EyeOutlined, EyeInvisibleOutlined } from '@ant-design/icons';
import { Input } from 'antd';

function Login () {
  const [userNameInput, setUserNameInput] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const toggleShowPassword = () => {setShowPassword(!showPassword)};

  const passwordIcon = showPassword ? <EyeOutlined onClick={toggleShowPassword} /> : <EyeInvisibleOutlined onClick={toggleShowPassword} />;

  function toProperCase(str) {
    return str
      .toLowerCase()
      .split(' ')
      .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
      .join(' ');
  }

  useEffect(() => {
    if(localStorage.getItem('user')){
      window.location.reload()
    }
  },[])

  const checkUserDetails = async(event) => {
    setLoading(true);
    event.preventDefault();
      if(userNameInput.trim() === '' || password === ''){
        setTimeout(() => {
          message.info("Please Enter User Name and Password")
        })
        return
      }
      try{
       const encodedPassw = encodeURI(password)
        const response = await api.get('/Login.php/get',{
          params:{
            JsonUserName: userNameInput,
            JsonPassword: encodedPassw
          }
        })
        if(response.data === 'Login Succesfully'){
          localStorage.setItem('user', toProperCase(userNameInput.trim()))
          //onLogin(userNameInput.trim());
          window.location.reload()
          //navigate('/')
          //navigation.navigate('Main', { userNameInput }); 
        }else{
          if(response.data === "Wrong UserName"){
            alert("The User ID does not exists. Contact your coach to create User ID")
          } else{
            setTimeout(() => {
              message.error("Wrong Password!")
            })
          }
          setLoading(false);
        } 
    } catch(error){
      console.error(error)
  }}

  const handleChange = (e) => {
      setUserNameInput(e.target.value.trim());
  }

  return (
    <div className='main'>   
      <div className='sub-main'>
        <form onSubmit={checkUserDetails}>    
        <div className='imgs'>   
          <div className='container-image'>
            <img src = {logo} className = 'profile' alt = 'profile' />
          </div>
        </div>
        <div>
          <div>
            <input 
          // style={styles.input}
            id='userNameInput'
            name = 'userNameInput'
            value={userNameInput}
            placeholder = "User Name"
            onChange={handleChange}
            // maxLength = {12}
            />
          </div>
          <div className="second-input">
            <Input.Password
            id = 'inputPassword'
            name='inputPassword'
            // style={styles.input}
            style={{
              padding: '10px',
              border: '2px solid #ccc',
              borderRadius: '10px',
              fontSize: '16px',
              fontFamily: "'Poppins', sans-serif",
              borderColor: '#2ea93f',
              borderWidth: '2px',
              width: '240px'
            }}
              defaultValue={password}
              placeholder = "Password"
              type={showPassword ? "text" : "password"}
              onChange={e => setPassword(e.target.value)}
            // maxLength = {12}
            iconRender={() => passwordIcon}
            />
          </div>
          <div>
            <button type="submit" className='login-button'>Login</button>
          </div>
          <br></br>
          <div>
            <h5 className='normal-label'>V: 3.2.1</h5>
          </div>
          {loading && 
            <div className='load-container'>
              <Spin />
            </div>
          }
          </div>
        </form>
      </div>
    </div>
  );
}

export default Login;